   265	/// What a log dump contained, summed over all lines added so far.
   266	#[derive(Debug, Default, Clone, PartialEq, Eq)]
   267	pub struct Stats {
   268	    pub lines: u64,
   269	    pub rejected_lines: u64,
   270	    pub timestamps: u64,
   271	    pub pairs: u64,
   272	    pub words: u64,
