   275	impl Stats {
   276	    /// Counts the tokens of one line. A line with a malformed token counts as rejected from that token on.
   277	    pub fn add_line(&mut self, line: &str) {
   278	        self.lines += 1;
   279	        for token in tokenize(line) {
   280	            match token {
   281	                Ok(Token::Timestamp(_)) => self.timestamps += 1,
   282	                Ok(Token::Key(_)) => self.pairs += 1,
   283	                Ok(Token::Word(_)) => self.words += 1,
   284	                Ok(Token::Quoted(_) | Token::Bare(_)) => {}
   285	                Err(_) => {
   286	                    self.rejected_lines += 1;
   287	                    break;
   288	                }
   289	            }
   290	        }
   291	    }
   292	}
   293	# logscan
   294	
   295	Reads structured log lines from stdin and prints how many lines, timestamps, `key=value` pairs and bare words it
   296	saw. The nightly import runs it over log dumps of several gigabytes, so the tokenizer is on the hot path: it
   297	borrows every token from the input line and does not allocate.
   298	
   299	```console
   300	$ printf '[2024-05-01T12:00:00Z] level=info msg="started \\"worker\\"" user=ann\n' | logscan
   301	lines: 1
   302	rejected lines: 0
   303	timestamps: 1
   304	pairs: 3
   305	words: 0
   306	```
   307	
   308	## Line format
   309	
   310	```text
   311	[2024-05-01T12:00:00Z] level=info msg="disk 91% full" retries= done
   312	```
   313	
   314	- `[...]` is a timestamp. It is kept as written, without the brackets.
   315	- `key=value` is a pair. The value is bare (up to the next space or tab, may be empty) or double-quoted. A quoted
   316	  value may contain spaces and the escapes `\"`, `\\`, `\n` and `\t`; it is handed out as written, escapes
   317	  included. `logscan::unescape` resolves them for callers that need the text.
   318	- Anything else up to the next space or tab is a word.
   319	- Tokens are separated by spaces or tabs. The first malformed token ends the line's token stream with an error.
   320	
   321	## Development
   322	
   323	```console
   324	cargo test
   325	```
use logscan::{tokenize, LexError, Token};

fn tokens(line: &str) -> Result<Vec<Token<'_>>, LexError> {
    tokenize(line).collect()
}

#[test]
fn reads_a_typical_line() {
    assert_eq!(
        tokens("[2024-05-01T12:00:00Z] level=info msg=\"disk 91% full\" user=ann").unwrap(),
        vec![
            Token::Timestamp("2024-05-01T12:00:00Z"),
            Token::Key("level"),
            Token::Bare("info"),
            Token::Key("msg"),
            Token::Quoted("disk 91% full"),
            Token::Key("user"),
            Token::Bare("ann"),
        ]
    );
}

#[test]
fn quoted_values_keep_their_escapes() {
    assert_eq!(
        tokens(r#"msg="say \"hi\"\n""#).unwrap(),
        vec![Token::Key("msg"), Token::Quoted(r#"say \"hi\"\n"#)]
    );
}

#[test]
fn words_stand_alone() {
    assert_eq!(
        tokens("started worker-3 ok").unwrap(),
        vec![Token::Word("started"), Token::Word("worker-3"), Token::Word("ok")]
    );
}

#[test]
fn tabs_separate_tokens_like_spaces() {
    assert_eq!(
        tokens("a=1\tb=2").unwrap(),
        vec![Token::Key("a"), Token::Bare("1"), Token::Key("b"), Token::Bare("2")]
    );
}

#[test]
fn empty_line_has_no_tokens() {
    assert_eq!(tokens("").unwrap(), vec![]);
    assert_eq!(tokens("   \t ").unwrap(), vec![]);
}

#[test]
fn unterminated_quote_is_an_error() {
    assert_eq!(
        tokens("msg=\"never closed"),
        Err(LexError::UnterminatedQuote { pos: 4 })
    );
}

#[test]
fn unterminated_timestamp_is_an_error() {
    assert_eq!(
        tokens("[2024-05-01 level=info"),
        Err(LexError::UnterminatedTimestamp { pos: 0 })
    );
}

#[test]
fn iteration_stops_after_an_error() {
    let mut stream = tokenize("ok =bad later=1");
    assert_eq!(stream.next(), Some(Ok(Token::Word("ok"))));
    assert_eq!(stream.next(), Some(Err(LexError::EmptyKey { pos: 3 })));
    assert_eq!(stream.next(), None);
}
