use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// What the tokenizer expects at its current position.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Expect {
    /// A timestamp, key or word, possibly after separators.
    Token,
    /// The value right after a key's `=`.
    Value,
    /// Nothing: the line ended in an error.
    Done,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    expect: Expect,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, expect: Expect::Token }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let lexed = match self.expect {
            Expect::Token => {
                self.pos = skip_separators(self.src.as_bytes(), self.pos);
                if self.pos == self.src.len() {
                    return None;
                }
                lex_token(self.src, self.pos)
            }
            Expect::Value => lex_value(self.src, self.pos),
            Expect::Done => return None,
        };
        match lexed {
            Ok((token, end)) => {
                self.pos = end;
                self.expect = if matches!(token, Token::Key(_)) { Expect::Value } else { Expect::Token };
                Some(Ok(token))
            }
            Err(error) => {
                self.pos = self.src.len();
                self.expect = Expect::Done;
                Some(Err(error))
            }
        }
    }
}

/// A token and the byte offset just past it.
type Lexed<'a> = Result<(Token<'a>, usize), LexError>;

fn is_separator(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

fn skip_separators(bytes: &[u8], mut pos: usize) -> usize {
    while pos < bytes.len() && is_separator(bytes[pos]) {
        pos += 1;
    }
    pos
}

/// Lexes the timestamp, key or word starting at the non-separator byte `start`.
fn lex_token(src: &str, start: usize) -> Lexed<'_> {
    match src.as_bytes()[start] {
        b'[' => lex_timestamp(src, start),
        b'"' => Err(LexError::UnexpectedQuote { pos: start }),
        b'=' => Err(LexError::EmptyKey { pos: start }),
        _ => lex_key_or_word(src, start),
    }
}

/// Lexes the value after a key's `=`, which may be empty, quoted or bare.
fn lex_value(src: &str, start: usize) -> Lexed<'_> {
    match src.as_bytes().get(start) {
        None => Ok((Token::Bare(""), start)),
        Some(&byte) if is_separator(byte) => Ok((Token::Bare(""), start)),
        Some(b'"') => lex_quoted(src, start),
        Some(_) => {
            let end = scan_unquoted(src.as_bytes(), start, is_separator)?;
            Ok((Token::Bare(&src[start..end]), end))
        }
    }
}

fn lex_timestamp(src: &str, open: usize) -> Lexed<'_> {
    let bytes = src.as_bytes();
    let mut i = open + 1;
    loop {
        match bytes.get(i) {
            None => return Err(LexError::UnterminatedTimestamp { pos: open }),
            Some(b']') => break,
            Some(b'[') => return Err(LexError::NestedBracket { pos: i }),
            Some(_) => i += 1,
        }
    }
    let end = i + 1;
    expect_separator(bytes, end)?;
    Ok((Token::Timestamp(&src[open + 1..i]), end))
}

fn lex_key_or_word(src: &str, start: usize) -> Lexed<'_> {
    let bytes = src.as_bytes();
    let end = scan_unquoted(bytes, start, |byte| is_separator(byte) || byte == b'=')?;
    if bytes.get(end) == Some(&b'=') {
        Ok((Token::Key(&src[start..end]), end + 1))
    } else {
        Ok((Token::Word(&src[start..end]), end))
    }
}

fn lex_quoted(src: &str, open: usize) -> Lexed<'_> {
    let bytes = src.as_bytes();
    let unterminated = LexError::UnterminatedQuote { pos: open };
    let mut i = open + 1;
    loop {
        match bytes.get(i) {
            None => return Err(unterminated),
