        for l in &lines { for tok in old::tokenize(black_box(l)) { if tok.is_ok() { c += 1 } } }
        let to = t.elapsed(); black_box(c);
        let t = Instant::now(); let mut c2 = 0usize;
        for l in &lines { for tok in new::tokenize(black_box(l)) { if tok.is_ok() { c2 += 1 } } }
